//! Values taken automatically from NVIDIA's published headers, version 570.144.
//!
//! `regs.rs`, `structs.rs`, `sysinfo.rs` and `rmapi.rs` are GENERATED by `tools/gen-rm570/generate.sh`
//! from NVIDIA open-gpu-kernel-modules (tag 570.144, MIT, notice in
//! `LICENSE-NVIDIA`). They are the specification, not a driver: this crate
//! performs no register access and contains no code that runs on the GPU.
//! It exists so hand-written offsets elsewhere (`nvidia-ga104`) can be checked
//! against the official headers instead of against our own reading of them.
//!
//! Only this file and the tests are hand-written.

#![cfg_attr(not(test), no_std)]
#![forbid(unsafe_code)]

pub mod regs;
pub mod rmapi;
pub mod structs;
pub mod sysinfo;

/// The firmware version the generated values belong to.
pub const RM_VERSION: &str = "570.144";

/// A register bit field `hi:lo` as written in NVIDIA's headers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Field {
    pub hi: u8,
    pub lo: u8,
}

impl Field {
    pub const fn new(hi: u8, lo: u8) -> Self {
        assert!(hi >= lo && hi < 32);
        Field { hi, lo }
    }

    pub const fn width(self) -> u32 {
        (self.hi - self.lo) as u32 + 1
    }

    pub const fn mask(self) -> u32 {
        (u32::MAX >> (32 - self.width())) << self.lo
    }

    /// Extract the field from a register value.
    pub const fn get(self, reg: u32) -> u32 {
        (reg & self.mask()) >> self.lo
    }

    /// Return `reg` with the field replaced by `v` (bits of `v` that do not
    /// fit are dropped). Pure arithmetic; nothing is written anywhere.
    pub const fn set(self, reg: u32, v: u32) -> u32 {
        (reg & !self.mask()) | ((v << self.lo) & self.mask())
    }
}

/// A bit field `hi:lo` of a page-table entry (64-bit PDE/PTE or 128-bit dual
/// PDE), as written in NVIDIA's `dev_mmu.h`. Pure arithmetic on a `u128`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EntryField {
    pub hi: u8,
    pub lo: u8,
}

impl EntryField {
    pub const fn new(hi: u8, lo: u8) -> Self {
        assert!(hi >= lo && hi < 128);
        EntryField { hi, lo }
    }

    pub const fn width(self) -> u32 {
        (self.hi - self.lo) as u32 + 1
    }

    pub const fn mask(self) -> u128 {
        (u128::MAX >> (128 - self.width())) << self.lo
    }

    pub const fn get(self, entry: u128) -> u128 {
        (entry & self.mask()) >> self.lo
    }

    /// `entry` with the field set to `v`, or `None` if `v` does not fit
    /// (never silently truncated: a cut address would point elsewhere).
    pub const fn set(self, entry: u128, v: u128) -> Option<u128> {
        if self.width() < 128 && v >> self.width() != 0 {
            return None;
        }
        Some((entry & !self.mask()) | (v << self.lo))
    }
}

/// A field of a 2048-bit QMD, as `MW(hi:lo)` in NVIDIA's QMD headers: bit
/// positions counted from bit 0 of the first little-endian u32.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct QmdField {
    pub hi: u32,
    pub lo: u32,
}

/// Size of a QMD V03_00 in bytes (2048 bits; `MW` positions stop at 2047).
pub const QMD_SIZE: usize = 256;

impl QmdField {
    pub const fn new(hi: u32, lo: u32) -> Self {
        assert!(hi >= lo && hi < 8 * QMD_SIZE as u32 && hi - lo < 32);
        QmdField { hi, lo }
    }

    pub const fn width(self) -> u32 {
        self.hi - self.lo + 1
    }

    /// Writes `v` (must fit in the field) into a QMD held as 64 u32 words.
    /// Fields never cross a 32-bit word in V03_00 (checked by a test).
    pub fn set(self, qmd: &mut [u32; QMD_SIZE / 4], v: u32) -> Result<(), &'static str> {
        if self.width() < 32 && v >> self.width() != 0 {
            return Err("valoare prea mare pentru campul QMD");
        }
        if self.lo / 32 != self.hi / 32 {
            return Err("campul QMD trece peste un cuvant de 32 de biti");
        }
        let f = Field::new((self.hi % 32) as u8, (self.lo % 32) as u8);
        let w = &mut qmd[(self.lo / 32) as usize];
        *w = f.set(*w, v);
        Ok(())
    }

    pub fn get(self, qmd: &[u32; QMD_SIZE / 4]) -> u32 {
        let f = Field::new((self.hi % 32) as u8, (self.lo % 32) as u8);
        f.get(qmd[(self.lo / 32) as usize])
    }
}

/// A device's register window `lo..=hi` (e.g. `NV_PGSP`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Range {
    pub lo: u32,
    pub hi: u32,
}

impl Range {
    pub const fn new(lo: u32, hi: u32) -> Self {
        assert!(lo <= hi);
        Range { lo, hi }
    }

    pub const fn contains(self, off: u32) -> bool {
        off >= self.lo && off <= self.hi
    }
}

/// `GspFwWprMeta.magic` as an unsigned value (bindgen emits it as i64).
pub const GSP_FW_WPR_META_MAGIC: u64 = structs::GSP_FW_WPR_META_MAGIC as u64;
/// `GspFwWprMeta.verified` once the booter accepted it.
pub const GSP_FW_WPR_META_VERIFIED: u64 = structs::GSP_FW_WPR_META_VERIFIED as u64;

#[cfg(test)]
mod tests {
    use super::regs::*;
    use super::structs::{
        GSP_ARGUMENTS_CACHED, GSP_FW_WPR_META_REVISION, GspFwWprMeta, MESSAGE_QUEUE_INIT_ARGUMENTS,
        MSGQ_FLAGS_SWAP_RX, MSGQ_VERSION, msgqRxHeader, msgqTxHeader,
    };
    use super::*;
    use core::mem::{offset_of, size_of};

    #[test]
    fn field_arithmetic() {
        let f = Field::new(7, 0);
        assert_eq!(f.mask(), 0xff);
        assert_eq!(f.get(0x1234_56ff), 0xff);
        let g = Field::new(31, 4);
        assert_eq!(g.mask(), 0xffff_fff0);
        assert_eq!(g.set(0xf, 0x1234), 0x0001_234f);
        assert_eq!(Field::new(31, 0).mask(), u32::MAX);
        assert_eq!(Field::new(0, 0).set(0, 3), 1);
    }

    /// Values the hub study (studiu/2026-10-26_open-source/gpu.md, lessons 3–5)
    /// read by hand; the generator must produce the same numbers.
    #[test]
    fn registers_match_the_study() {
        use ga102_dev_falcon_v4 as f;
        assert_eq!(f::NV_PFALCON_FALCON_MAILBOX0, 0x40);
        assert_eq!(f::NV_PFALCON_FALCON_MAILBOX1, 0x44);
        assert_eq!(f::NV_PFALCON_FALCON_OS, 0x80);
        assert_eq!(f::NV_PFALCON_FALCON_CPUCTL, 0x100);
        assert_eq!(f::NV_PFALCON_FALCON_BOOTVEC, 0x104);
        assert_eq!(f::NV_PFALCON_FALCON_DMATRFCMD, 0x118);
        assert_eq!(f::NV_PFALCON_FALCON_HWCFG2, 0xf4);

        use ga102_dev_gsp as g;
        assert_eq!(g::NV_PGSP, Range::new(0x110000, 0x113fff));
        assert_eq!(g::NV_PGSP_FALCON_MAILBOX0, 0x110040);
        assert_eq!(g::NV_PGSP_FALCON_ENGINE, 0x1103c0);
        assert_eq!(g::NV_PGSP_QUEUE_HEAD(0), 0x110c00);
        assert_eq!(g::NV_PGSP_QUEUE_HEAD(1), 0x110c08);
        assert_eq!(ga102_dev_sec_pri::NV_PSEC.lo, 0x840000);

        use ga102_dev_gc6_island_addendum as a;
        assert_eq!(
            a::NV_PGC6_AON_SECURE_SCRATCH_GROUP_05_0_GFW_BOOT_PROGRESS,
            Field::new(7, 0)
        );
        assert_eq!(a::NV_USABLE_FB_SIZE_IN_MB, 0x1183a4);
        assert_eq!(tu102_dev_fb::NV_PFB_PRI_MMU_WPR2_ADDR_HI, 0x1fa828);
        assert_eq!(
            tu102_dev_fb::NV_PFB_PRI_MMU_WPR2_ADDR_HI_VAL,
            Field::new(31, 4)
        );
    }

    /// Every register offset of the GSP falcon lies inside the GSP window.
    #[test]
    fn gsp_registers_inside_gsp_window() {
        use ga102_dev_gsp as g;
        for off in [
            g::NV_PGSP_FALCON_MAILBOX0,
            g::NV_PGSP_FALCON_ENGINE,
            g::NV_PGSP_QUEUE_HEAD(0),
        ] {
            assert!(g::NV_PGSP.contains(off), "{off:#x}");
        }
    }

    /// Sizes and offsets the study names (lesson 9; proposal B first step).
    /// bindgen also checks every field at compile time; these are the ones
    /// our driver depends on, written out so a regeneration that changes
    /// them fails here with a readable name.
    #[test]
    fn structures_match_the_study() {
        assert_eq!(size_of::<GspFwWprMeta>(), 256);
        assert_eq!(offset_of!(GspFwWprMeta, magic), 0);
        assert_eq!(offset_of!(GspFwWprMeta, revision), 8);
        assert_eq!(offset_of!(GspFwWprMeta, verified), 248);
        assert_eq!(GSP_FW_WPR_META_MAGIC, 0xdc3a_ae21_371a_60b3);
        assert_eq!(GSP_FW_WPR_META_REVISION, 1);
        assert_eq!(GSP_FW_WPR_META_VERIFIED, 0xa0a0_a0a0_a0a0_a0a0);

        assert_eq!(size_of::<msgqTxHeader>(), 32);
        assert_eq!(offset_of!(msgqTxHeader, entryOff), 28);
        assert_eq!(size_of::<msgqRxHeader>(), 4);
        assert_eq!(MSGQ_VERSION, 0);
        assert_eq!(MSGQ_FLAGS_SWAP_RX, 1);

        assert_eq!(size_of::<GSP_ARGUMENTS_CACHED>(), 72);
        assert_eq!(size_of::<MESSAGE_QUEUE_INIT_ARGUMENTS>(), 32);
    }

    /// The QMD V03_00 layout from open-gpu-doc: every field fits the 2048
    /// bits and no field crosses a 32-bit word (so `QmdField::set` is enough).
    #[test]
    fn qmd_v03_00_layout_is_sane() {
        use qmd_v03_00 as q;
        assert!(q::ALL_FIELDS.len() > 100);
        for (name, f) in q::ALL_FIELDS {
            assert!(f.hi < 2048, "{name}");
            assert_eq!(f.lo / 32, f.hi / 32, "{name} crosses a word");
        }
        // The fields the first launch needs (study, lessons 15-16).
        assert_eq!(
            q::NVC6C0_QMDV03_00_CTA_RASTER_WIDTH,
            QmdField::new(415, 384)
        );
        assert_eq!(
            q::NVC6C0_QMDV03_00_CTA_THREAD_DIMENSION0,
            QmdField::new(607, 592)
        );
        assert_eq!(
            q::NVC6C0_QMDV03_00_RELEASE0_ADDRESS_LOWER,
            QmdField::new(799, 768)
        );
        assert_eq!(
            q::NVC6C0_QMDV03_00_CONSTANT_BUFFER_VALID(0),
            QmdField::new(640, 640)
        );
        let mut qmd = [0u32; QMD_SIZE / 4];
        q::NVC6C0_QMDV03_00_CTA_THREAD_DIMENSION0
            .set(&mut qmd, 64)
            .unwrap();
        assert_eq!(qmd[18], 64 << 16);
        assert_eq!(q::NVC6C0_QMDV03_00_CTA_THREAD_DIMENSION0.get(&qmd), 64);
        assert!(
            q::NVC6C0_QMDV03_00_CTA_THREAD_DIMENSION0
                .set(&mut qmd, 1 << 16)
                .is_err()
        );
    }

    #[test]
    fn launch_methods_match_the_study() {
        assert_eq!(clc56f::AMPERE_CHANNEL_GPFIFO_A, 0xc56f);
        assert_eq!(clc56f::NVC56F_SEM_EXECUTE, 0x6c);
        assert_eq!(clc7c0::AMPERE_COMPUTE_B, 0xc7c0);
        assert_eq!(clc7c0::NVC7C0_SEND_PCAS_A, 0x2b4);
        assert_eq!(clc7c0::NVC7C0_SEND_SIGNALING_PCAS2_B, 0x2c0);
    }

    /// I9: the MMU v2 entry formats (UVM's full `dev_mmu.h`), as read by hand
    /// for `gpu_sim::vram`; the dual PDE's small half lives in bits 64..127.
    #[test]
    fn mmu_ver2_formats_match_the_hand_reading() {
        use tu102_dev_mmu_ver2 as m;
        assert_eq!(m::NV_MMU_VER2_PDE_APERTURE, EntryField::new(2, 1));
        assert_eq!(m::NV_MMU_VER2_PDE_ADDRESS_VID, EntryField::new(32, 8));
        assert_eq!(m::NV_MMU_VER2_PDE_NO_ATS, EntryField::new(5, 5));
        assert_eq!(
            m::NV_MMU_VER2_DUAL_PDE_APERTURE_SMALL,
            EntryField::new(66, 65)
        );
        assert_eq!(
            m::NV_MMU_VER2_DUAL_PDE_ADDRESS_SMALL_VID,
            EntryField::new(96, 72)
        );
        assert_eq!(
            m::NV_MMU_VER2_DUAL_PDE_ADDRESS_BIG_VID,
            EntryField::new(32, 4)
        );
        assert_eq!(m::NV_MMU_VER2_DUAL_PDE_ADDRESS_BIG_SHIFT, 8);
        assert_eq!(m::NV_MMU_VER2_PTE_VALID, EntryField::new(0, 0));
        assert_eq!(m::NV_MMU_VER2_PTE_VOL, EntryField::new(3, 3));
        assert_eq!(m::NV_MMU_VER2_PTE_KIND, EntryField::new(63, 56));
        // PTE aperture 0 = video memory; PDE aperture 1 = video memory.
        assert_eq!(m::NV_MMU_VER2_PTE_APERTURE_VIDEO_MEMORY, 0);
        assert_eq!(m::NV_MMU_VER2_PDE_APERTURE_VIDEO_MEMORY, 1);
        assert_eq!(
            (
                m::NV_MMU_VER2_PDE__SIZE,
                m::NV_MMU_VER2_DUAL_PDE__SIZE,
                m::NV_MMU_VER2_PTE__SIZE
            ),
            (8, 16, 8)
        );
        // EntryField arithmetic, including a field above bit 64.
        let f = m::NV_MMU_VER2_DUAL_PDE_ADDRESS_SMALL_VID;
        let e = f.set(0, 0x1ff_ffff).unwrap();
        assert_eq!(f.get(e), 0x1ff_ffff);
        assert_eq!(e >> 64, 0x1ff_ffff << 8);
        assert_eq!(f.set(0, 1 << 25), None); // would be cut: refused
        assert_eq!(EntryField::new(127, 0).set(0, u128::MAX), Some(u128::MAX));
    }

    #[test]
    fn version_is_pinned() {
        assert_eq!(RM_VERSION, "570.144");
    }
}

#[cfg(test)]
mod rmapi_tests {
    use super::rmapi::*;
    use core::mem::{offset_of, size_of};

    /// I8e: sizes computed by clang from the 570.144 headers (via bindgen).
    /// Written down here so a regeneration that changes them is noticed;
    /// `gpu_sim::fake_rm` repeats them independently.
    #[test]
    fn rm_api_layouts_570_144() {
        assert_eq!((RPC_GSP_RM_ALLOC_PARAMS, RPC_GSP_RM_ALLOC_SIZEOF), (32, 32));
        assert_eq!(
            (RPC_GSP_RM_CONTROL_PARAMS, RPC_GSP_RM_CONTROL_SIZEOF),
            (24, 24)
        );
        assert_eq!(RPC_GSP_RM_ALLOC_STATUS, 16);
        assert_eq!(RPC_GSP_RM_CONTROL_STATUS, 12);
        assert_eq!(size_of::<NV0000_ALLOC_PARAMETERS>(), 120);
        assert_eq!(size_of::<NV0080_ALLOC_PARAMETERS>(), 56);
        assert_eq!(size_of::<NV2080_ALLOC_PARAMETERS>(), 4);
        assert_eq!(size_of::<NV_VASPACE_ALLOCATION_PARAMETERS>(), 48);
        assert_eq!(size_of::<NV_CHANNEL_ALLOC_PARAMS>(), 368);
        assert_eq!(size_of::<NV_MEMORY_DESC_PARAMS>(), 24);
        assert_eq!(
            size_of::<NV2080_CTRL_FIFO_GET_DEVICE_INFO_TABLE_PARAMS>(),
            3212
        );
        assert_eq!(
            size_of::<NV90F1_CTRL_VASPACE_COPY_SERVER_RESERVED_PDES_PARAMS>(),
            184
        );
        assert_eq!(
            size_of::<NV2080_CTRL_INTERNAL_STATIC_KGR_GET_CONTEXT_BUFFERS_INFO_PARAMS>(),
            1664
        );
        assert_eq!(size_of::<NV2080_CTRL_GPU_PROMOTE_CTX_PARAMS>(), 560);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, hVASpace), 28);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, engineType), 128);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, internalFlags), 244);
        assert_eq!(
            offset_of!(NV2080_CTRL_GPU_PROMOTE_CTX_PARAMS, promoteEntry),
            48
        );
        assert_eq!(
            [
                AMPERE_CHANNEL_GPFIFO_A,
                AMPERE_COMPUTE_B,
                AMPERE_DMA_COPY_B,
                FERMI_VASPACE_A,
                NV20_SUBDEVICE_0,
                NV01_DEVICE_0
            ],
            [0xc56f, 0xc7c0, 0xc7b5, 0x90f1, 0x2080, 0x80]
        );
        assert_eq!(NV2080_CTRL_CMD_GPU_PROMOTE_CTX, 0x2080_012b);
        assert_eq!(GMMU_FMT_MAX_LEVELS, 6);
        // I9c: the SET_PAGE_DIRECTORY RPC.
        assert_eq!(size_of::<rpc_set_page_directory_v1E_05>(), 48);
        assert_eq!(offset_of!(rpc_set_page_directory_v1E_05, params), 16);
        assert_eq!(
            size_of::<NV0080_CTRL_DMA_SET_PAGE_DIRECTORY_PARAMS_v1E_05>(),
            32
        );
        assert_eq!(NV0080_CTRL_CMD_DMA_SET_PAGE_DIRECTORY, 0x80_1813);
        assert_eq!(NV_DEVICE_ALLOCATION_VAMODE_OPTIONAL_MULTIPLE_VASPACES, 0);
        // I9d: channel group (TSG) and context share.
        assert_eq!(size_of::<NV_CHANNEL_GROUP_ALLOCATION_PARAMETERS>(), 20);
        assert_eq!(
            offset_of!(NV_CHANNEL_GROUP_ALLOCATION_PARAMETERS, engineType),
            12
        );
        assert_eq!(size_of::<NV_CTXSHARE_ALLOCATION_PARAMETERS>(), 12);
        assert_eq!(offset_of!(NV_CTXSHARE_ALLOCATION_PARAMETERS, subctxId), 8);
        assert_eq!(
            (KEPLER_CHANNEL_GROUP_A, FERMI_CONTEXT_SHARE_A),
            (0xa06c, 0x9067)
        );
        assert_eq!(NV2080_ENGINE_TYPE_GRAPHICS, NV2080_ENGINE_TYPE_GR0);
        assert_eq!(NV_CTXSHARE_ALLOCATION_FLAGS_SUBCONTEXT_ASYNC, 1);
        // I9e: the work submit token and the TSG schedule controls.
        assert_eq!(
            size_of::<NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN_PARAMS>(),
            4
        );
        assert_eq!(size_of::<NVA06F_CTRL_GPFIFO_SCHEDULE_PARAMS>(), 2);
        assert_eq!(NVC36F_CTRL_CMD_GPFIFO_GET_WORK_SUBMIT_TOKEN, 0xc36f_0108);
        assert_eq!(NVA06C_CTRL_CMD_GPFIFO_SCHEDULE, 0xa06c_0101);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, hContextShare), 24);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, hUserdMemory), 32);
        assert_eq!(offset_of!(NV_CHANNEL_ALLOC_PARAMS, errorNotifierMem), 248);
        // I10a: USERD (clc56f.h `AmpereAControlGPFifo`) — GPGet read-only, GPPut ours.
        assert_eq!(size_of::<AmpereAControlGPFifo>(), 512);
        assert_eq!(offset_of!(AmpereAControlGPFifo, GPGet), 0x88);
        assert_eq!(offset_of!(AmpereAControlGPFifo, GPPut), 0x8c);
    }
}
